UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Myasthenia Gravis","body":"**Myasthenia Gravis - Fluctuating Diplopia:**\n\n**Key Features:**\n• **Fluctuating** ptosis and diplopia\n• **Fatigable** weakness (worse with sustained use)\n• **Worse in evening** or with fatigue\n• >50% present with isolated ocular symptoms initially\n\n**Bedside Tests:**\n\n**Ice Pack Test:**\n1. Apply ice pack to closed eyelid for 2-5 minutes\n2. Positive: Ptosis improves ≥2mm\n3. **Sensitivity ~77%, Specificity ~98%** (no false-positives in myasthenic-diplopia study); sensitivity drops in complete or very mild ptosis — a negative test does NOT exclude MG\n4. Cold inhibits acetylcholinesterase\n\n**Sustained Upgaze Test:**\n• Have patient look up for 60 seconds\n• Positive: Ptosis worsens or develops\n\n**Confirmatory Testing:**\n• AChR antibodies: 50-70% sensitive in ocular MG\n• Single fiber EMG: ~95% sensitive\n• Anti-MuSK antibodies if AChR negative\n\n**⚠️ Red Flag - Myasthenic Crisis:**\n• Respiratory weakness (FVC <1L or <15 mL/kg)\n• Bulbar symptoms (dysphagia, dysarthria)\n• Requires ICU admission [12][13]","citation":[12,13],"next":"diplopia-mg-disposition","images":[{"src":"images/diplopia/ice-pack-test.png","alt":"Ice pack test for myasthenia gravis showing improvement of ptosis after 2-5 minutes of ice application","caption":"Ice pack test: Apply ice to ptotic lid for 2-5 min. Improvement ≥2mm = positive for MG."}],"summary":"Myasthenia Gravis — review key clinical information before proceeding"}'::jsonb
